mapper.select:
SELECT NICKNAME
FROM MEMBER
WHERE MEMBER_SEQ = #{memberSeq}

SELECT * FROM ( SELECT a.*, ROWNUM AS RN FROM ( SELECT , (SELECT LISTAGG(h.TAG, ',') WITHIN GROUP (ORDER BY h.LIVE_HASHTAG_SEQ) FROM LIVE_HASHTAG h WHERE h.LIVE_ROOM_SEQ = r.LIVE_ROOM_SEQ) AS HASHTAG_TEXT FROM LIVE_ROOM r JOIN MEMBER m ON m.MEMBER_SEQ = r.HOST_SEQ WHERE r.STATUS = 'LIVE'
AND r.CATEGORY = #{category}
AND (INSTR(r.TITLE, #{keyword}) > 0 OR INSTR(m.NICKNAME, #{keyword}) > 0)
ORDER BY VIEWER_COUNT DESC, r.STARTED_AT DESC, r.LIVE_ROOM_SEQ DESC ) a WHERE ROWNUM <= #{endRow} ) WHERE RN > #{startRow}

SELECT COUNT(*)
FROM LIVE_VIEWER
WHERE LIVE_ROOM_SEQ = #{liveRoomSeq}
  AND MEMBER_SEQ = #{memberSeq}
  AND KICKED_YN = 'Y'

SELECT COUNT(*)
FROM LIVE_BAN
WHERE HOST_SEQ = #{hostSeq}
  AND MEMBER_SEQ = #{memberSeq}

mapper.update:
UPDATE LIVE_VIEWER
SET LEFT_AT = SYSTIMESTAMP
WHERE LIVE_ROOM_SEQ = #{liveRoomSeq}
  AND MEMBER_SEQ = #{memberSeq}
  AND LEFT_AT IS NULL

UPDATE LIVE_VIEWER
SET KICKED_YN = 'Y',
    LEFT_AT = NVL(LEFT_AT, SYSTIMESTAMP)
WHERE LIVE_ROOM_SEQ = #{liveRoomSeq}
  AND MEMBER_SEQ = #{memberSeq}

mapper.select:
SELECT COUNT(*)
FROM MEMBER
WHERE MEMBER_SEQ = #{memberSeq}

mapper.delete:
DELETE FROM LIVE_BAN
WHERE HOST_SEQ = #{hostSeq}
  AND MEMBER_SEQ = #{memberSeq}

mapper.select:
SELECT COUNT(*)
FROM LIVE_VIEWER
WHERE LIVE_ROOM_SEQ = #{liveRoomSeq}
  AND MEMBER_SEQ = #{memberSeq}
  AND LEFT_AT IS NULL
  AND KICKED_YN = 'N'

mapper.delete:
DELETE FROM LIVE_CHAT c
WHERE c.LIVE_ROOM_SEQ = #{liveRoomSeq}
  AND NOT EXISTS (
      SELECT 1 FROM LIVE_REPORT rp
      WHERE rp.LIVE_CHAT_SEQ = c.LIVE_CHAT_SEQ
  )

mapper.select:
SELECT LIVE_CHAT_SEQ, LIVE_ROOM_SEQ, MEMBER_SEQ, CONTENT, CREATED_AT
FROM LIVE_CHAT
WHERE LIVE_CHAT_SEQ = #{liveChatSeq}

SELECT COUNT(*)
FROM LIVE_REPORT
WHERE LIVE_ROOM_SEQ = #{liveRoomSeq}
  AND REPORTER_SEQ = #{reporterSeq}
  AND STATUS = 'WAIT'

  AND LIVE_CHAT_SEQ = #{liveChatSeq}
  AND LIVE_CHAT_SEQ IS NULL

SELECT * FROM ( SELECT a.*, ROWNUM AS RN FROM ( SELECT rp.LIVE_REPORT_SEQ, rp.LIVE_ROOM_SEQ, rp.LIVE_CHAT_SEQ, rp.REPORTER_SEQ, rp.REASON, rp.DETAIL, rp.STATUS, rp.CREATED_AT, r.TITLE AS ROOM_TITLE, r.STATUS AS ROOM_STATUS, r.HOST_SEQ, hm.NICKNAME AS HOST_NICKNAME, rm.NICKNAME AS REPORTER_NICKNAME, c.CONTENT AS CHAT_CONTENT, c.MEMBER_SEQ AS CHAT_MEMBER_SEQ, cm.NICKNAME AS CHAT_MEMBER_NICKNAME FROM LIVE_REPORT rp JOIN LIVE_ROOM r ON r.LIVE_ROOM_SEQ = rp.LIVE_ROOM_SEQ JOIN MEMBER hm ON hm.MEMBER_SEQ = r.HOST_SEQ JOIN MEMBER rm ON rm.MEMBER_SEQ = rp.REPORTER_SEQ LEFT JOIN LIVE_CHAT c ON c.LIVE_CHAT_SEQ = rp.LIVE_CHAT_SEQ LEFT JOIN MEMBER cm ON cm.MEMBER_SEQ = c.MEMBER_SEQ
WHERE rp.STATUS = #{status}
ORDER BY rp.CREATED_AT DESC, rp.LIVE_REPORT_SEQ DESC ) a WHERE ROWNUM <= #{endRow} ) WHERE RN > #{startRow}
